private static function updateMeta(string $category, Request $request, Response $response): Response {
  $requestBody = JSON::decode($request->getBody()->getContents());

  if (!is_object($requestBody)) {
    return $response;
  }

  foreach ($requestBody as $key => $value) {
    $valueAsString = (is_string($value) or is_null($value)) ? $value : json_encode($value);
    self::adminDAO()->setMeta($category, $key, $valueAsString);
  }

  return $response;
}

public function setMeta(string $category, string $key, ?string $value): void {
  $currentValue = $this->_('select value from meta where "metaKey" = :key', [':key' => $key]);

  if (!$currentValue) {
    $this->_(
      'insert into meta (category, "metaKey", value) values (:category, :key, :value)',
      [
        ':key' => $key,
        ':category' => $category,
        ':value' => $value
      ]
    );
  } else {
    $this->_(
      'update meta set value=:value, category=:category where "metaKey" = :key',
      [
        ':key' => $key,
        ':category' => $category,
        ':value' => $value
      ]
    );
  }
}

saveData():void {
  this.backendService.setCustomTexts(this.changedData)
    .subscribe(() => {
      if (!this.mainDataService.appConfig) {
        throw new AppError({
          description: '',
          label: 'appConfig not yet loaded',
          type: 'script'
        });
      }
      this.messageService.showSnackbar('Textersetzungen gespeichert');
      this.dataChanged = false;
      Object.keys(this.changedData).forEach(ctKey => {
        (this.mainDataService.appConfig as AppConfig).customTexts[ctKey] = this.changedData[ctKey];
      });
      this.customtextService.addCustomTexts(this.changedData);
    });
}

CREATE TABLE meta (
  "metaKey" varchar(100) NOT NULL,
  value     text,
  category  varchar(30) DEFAULT NULL,
  CONSTRAINT meta_pk UNIQUE ("metaKey", category)
);

